insert into series (id, slug, name, year, timeline, format, color, synopsis, image_url) values
  (1, 'mobile-suit-gundam', 'Mobile Suit Gundam', 1979, 'Universal Century 0079', 'TV', '#e63946', 'Perang Satu Tahun antara Federasi Bumi dan Kerajaan Zeon. Amuro Ray, remaja yang tinggal di koloni luar angkasa, terseret ke medan perang ketika ia menaiki prototipe RX-78-2 Gundam, dan perlahan berubah dari anak biasa menjadi pilot ulung. Serial yang melahirkan genre real robot.', null),
  (2, 'zeta-gundam', 'Mobile Suit Zeta Gundam', 1985, 'Universal Century 0087', 'TV', '#f4a261', 'Tujuh tahun setelah Perang Satu Tahun, Federasi dikuasai pasukan elit Titans. Kamille Bidan bergabung dengan AEUG untuk melawan mereka dan menjadi pilot Zeta Gundam, mobile suit yang bisa berubah menjadi pesawat tempur.', null),
  (3, 'gundam-zz', 'Mobile Suit Gundam ZZ', 1986, 'Universal Century 0088', 'TV', '#ffd166', 'Lanjutan Zeta Gundam dengan nuansa lebih ringan. Judau Ashta, pemuda pemulung dari koloni Shangri-La, menjadi pilot ZZ Gundam saat Neo Zeon yang dipimpin Haman Karn bangkit memperebutkan kekuasaan.', null),
  (4, 'chars-counterattack', 'Mobile Suit Gundam: Char''s Counterattack', 1988, 'Universal Century 0093', 'Film', '#c1121f', 'Film layar lebar yang menutup rivalitas Amuro Ray dan Char Aznable. Char memimpin pasukan Neo Zeon dan berencana menjatuhkan asteroid Axis ke Bumi, sementara Amuro berusaha menghentikannya dengan ν Gundam.', null),
  (5, 'gundam-unicorn', 'Mobile Suit Gundam Unicorn', 2010, 'Universal Century 0096', 'OVA', '#7b9ea8', 'Banagher Links, siswa biasa, menemukan Unicorn Gundam dan terlibat dalam perburuan "Laplace''s Box", kunci rahasia yang bisa mengguncang tatanan politik Federasi dan sisa-sisa Zeon.', null),
  (6, 'gundam-wing', 'Mobile Suit Gundam Wing', 1995, 'After Colony 195', 'TV', '#4cc9f0', 'Lima pilot muda dari koloni luar angkasa dikirim ke Bumi dengan Gundam masing-masing untuk melawan Aliansi Bumi dan organisasi OZ. Heero Yuy, Duo Maxwell, Trowa Barton, Quatre Raberba Winner, dan Chang Wufei punya cara berbeda memaknai perang.', null),
  (7, 'g-gundam', 'Mobile Fighter G Gundam', 1994, 'Future Century', 'TV', '#f77f00', 'Setiap koloni mengirim satu Gundam Fighter ke turnamen Gundam Fight untuk menentukan penguasa koloni berikutnya. Domon Kasshu, pilot Shining Gundam dari Neo Japan, bertarung sambil mengejar kakaknya yang menghilang. Gayanya lebih mirip seni bela diri ketimbang perang.', null),
  (8, 'gundam-seed', 'Mobile Suit Gundam SEED', 2002, 'Cosmic Era 71', 'TV', '#3a86ff', 'Konflik antara Natural dan Coordinator, manusia hasil rekayasa genetika, meledak menjadi perang ORB, Aliansi Bumi, dan ZAFT. Kira Yamato, Coordinator yang tinggal di koloni netral, terpaksa menjadi pilot Strike Gundam dan harus berhadapan dengan sahabat lamanya, Athrun Zala.', null),
  (9, 'gundam-00', 'Mobile Suit Gundam 00', 2007, 'Anno Domini 2307', 'TV', '#2ec4b6', 'Organisasi bersenjata Celestial Being berambisi menghapus perang dengan intervensi bersenjata memakai Gundam bertenaga GN Drive. Setsuna F. Seiei, pilot Gundam Exia, mempertaruhkan hidupnya untuk idealisme itu di tengah dunia yang terbagi tiga blok kekuatan.', null),
  (10, 'iron-blooded-orphans', 'Mobile Suit Gundam: Iron-Blooded Orphans', 2015, 'Post Disaster 323', 'TV', '#9d4edd', 'Kelompok tentara anak Tekkadan, dipimpin Orga Itsuka, memberontak melawan perusahaan yang memperbudak mereka. Mikazuki Augus mengendalikan Gundam Barbatos, mobile frame kuno berusia ratusan tahun, dalam kisah yang suram dan penuh pengorbanan.', null),
  (11, 'witch-from-mercury', 'Mobile Suit Gundam: The Witch from Mercury', 2022, 'Ad Stella', 'TV', '#e0aaff', 'Suletta Mercury, siswi pindahan dari Merkurius, mendaftar ke Asticassia School of Technology dengan Gundam Aerial. Di sekolah yang semua urusannya diselesaikan lewat duel mobile suit, ia terlibat bersama Miorine Rembran dalam intrik perusahaan dan rahasia di balik teknologi Gundam.', null)
insert into mobile_suits (id, name, model_number, series_id, pilot, faction, unit_type, height_m, weight_t, armaments, description, image_url) values
  (1, 'Gundam', 'RX-78-2', 1, 'Amuro Ray', 'Earth Federation', 'Prototipe serbaguna', 18, 43.4, array['Beam Rifle', 'Beam Saber', '60mm Vulcan', 'Hyper Bazooka', 'Shield'], 'Mobile suit prototipe Federasi Bumi dari Proyek V. Armor Luna Titanium dan persenjataan beam membuatnya jauh melampaui Zaku. Di tangan Amuro Ray, unit ini menjadi simbol seluruh franchise.', null),
  (2, 'Guncannon', 'RX-77-2', 1, 'Kai Shiden', 'Earth Federation', 'Dukungan jarak jauh', 17.5, 53.2, array['240mm Cannon', 'Beam Rifle'], 'Mobile suit pendukung artileri dari Proyek V dengan dua meriam di pundak. Dalam serial ini dikemudikan Kai Shiden dan bertugas menembak dari belakang saat Gundam maju.', null),
  (3, 'Zaku II Commander Type (Char Custom)', 'MS-06S', 1, 'Char Aznable', 'Principality of Zeon', 'Unit komandan', 17.5, 56.2, array['Zaku Machine Gun', 'Heat Hawk', 'Zaku Bazooka'], 'Zaku II versi komandan yang dicat merah dan dikenal sebagai "Komet Merah". Mobilitasnya jauh di atas Zaku biasa dan menjadi ikon rival Amuro, Char Aznable.', null),
  (4, 'Gouf', 'MS-07B', 1, 'Ramba Ral', 'Principality of Zeon', 'Pertempuran darat', 18.7, 58.5, array['Heat Rod', 'Finger Vulcan', 'Shield with Machine Gun'], 'Mobile suit tempur darat Zeon yang lebih gesit dari Zaku. Terkenal dipakai Ramba Ral, ace Zeon yang dihormati lawan maupun kawan.', null),
  (5, 'Dom', 'MS-09', 1, 'Black Tri-Stars', 'Principality of Zeon', 'Serangan cepat', 18.6, 62.6, array['Giant Bazooka', 'Heat Saber'], 'Mobile suit bertubuh tambun dengan pendorong hover. Meski tampak berat, Dom sangat lincah di darat dan terkenal lewat formasi Jet Stream Attack milik Black Tri-Stars.', null),
  (6, 'Zeta Gundam', 'MSZ-006', 2, 'Kamille Bidan', 'AEUG', 'Transformable', 19.85, 28.7, array['Beam Rifle', 'Beam Saber', 'Hyper Mega Launcher'], 'Gundam transformable pertama yang berubah menjadi mode Waverider untuk penerbangan dan masuk atmosfer. Dirancang oleh Anaheim Electronics dan dikemudikan Kamille Bidan.', null),
  (7, 'Hyaku Shiki', 'MSN-00100', 2, 'Quattro Bajeena (Char Aznable)', 'AEUG', 'Unit komandan', 19.5, null, array['Beam Rifle', 'Beam Saber', 'Clay Bazooka'], 'Mobile suit berwarna emas yang dipakai Quattro Bajeena, identitas baru Char Aznable. Tampilan emasnya langsung mudah dikenali di medan perang.', null),
  (8, 'The O', 'PMX-003', 2, 'Paptimus Scirocco', 'Titans', 'Unit komandan', 28, null, array['Beam Rifle', 'Beam Saber', 'Sub-arms'], 'Mobile suit raksasa milik Paptimus Scirocco dari Titans. Dilengkapi lengan tambahan di punggung yang bisa memegang senjata, membuatnya terlihat mengintimidasi.', null),
  (9, 'ZZ Gundam', 'MSZ-010', 3, 'Judau Ashta', 'AEUG', 'Combining', null, null, array['Double Beam Rifle', 'Hi-Mega Cannon', 'Beam Saber'], 'Gundam yang tersusun dari beberapa bagian yang bisa dipisah dan digabung kembali. Senjata utamanya, Hi-Mega Cannon di dahi, punya daya hancur sangat besar.', null),
  (10, 'Qubeley', 'AMX-004', 3, 'Haman Karn', 'Neo Zeon', 'Newtype khusus', null, null, array['Funnel', 'Beam Saber'], 'Mobile suit khusus Newtype Neo Zeon dengan Funnel kendali pikiran. Haman Karn memakainya sebagai senjata utama dalam perebutan kekuasaan di era ZZ.', null),
  (11, 'ν Gundam (Nu Gundam)', 'RX-93', 4, 'Amuro Ray', 'Earth Federation', 'Newtype khusus', 22, 28.6, array['Fin Funnel', 'Beam Rifle', 'Beam Saber', 'Hyper Bazooka'], 'Gundam rancangan Amuro Ray sendiri dengan sistem Fin Funnel yang dikendalikan lewat pikiran. Ia menjadi lawan utama Sazabi dalam duel penutup rivalitas Amuro dan Char.', null),
  (12, 'Sazabi', 'MSN-04', 4, 'Char Aznable', 'Neo Zeon', 'Newtype khusus', 22, null, array['Funnel', 'Beam Shot Rifle', 'Beam Tomahawk'], 'Mobile suit merah milik Char yang menjadi pasangan sebanding ν Gundam. Memakai psycho-frame dan dipersenjatai Funnel di punggung, dirancang khusus untuk pilot Newtype.', null),
  (13, 'Unicorn Gundam', 'RX-0', 5, 'Banagher Links', 'Earth Federation', 'Transformable (NT-D)', 19.7, 23.7, array['Beam Magnum', 'Beam Saber', 'Shield'], 'Gundam dengan dua wujud: Unicorn Mode dengan satu tanduk, dan Destroy Mode dengan sistem NT-D ketika tanduknya terbelah menjadi V-fin dan armornya terbuka memperlihatkan psycho-frame merah.', null),
  (14, 'Sinanju', 'MSN-06S', 5, 'Full Frontal', 'Neo Zeon (Sleeves)', 'Newtype khusus', null, null, array['Beam Saber', 'Beam Rifle', 'Beam Axe'], 'Mobile suit merah-kuning milik Full Frontal, pemimpin Sleeves. Dibangun sebagai penerus Sazabi dan menjadi lawan utama Unicorn.', null),
  (15, 'Wing Gundam', 'XXXG-01W', 6, 'Heero Yuy', 'Koloni (Operation Meteor)', 'Transformable', 16.3, 7.4, array['Buster Rifle', 'Beam Saber', 'Machine Cannon'], 'Gundam utama Heero Yuy yang bisa berubah menjadi mode burung (bird mode). Terbuat dari Gundanium Alloy yang tahan terhadap hampir semua serangan konvensional.', null),
  (16, 'Gundam Deathscythe', 'XXXG-01D', 6, 'Duo Maxwell', 'Koloni (Operation Meteor)', 'Infiltrasi dan jarak dekat', null, null, array['Beam Scythe', 'Buster Shield', 'Active Cloak'], 'Gundam hitam Duo Maxwell dengan sabit beam raksasa. Dilengkapi Active Cloak yang membuatnya sulit terdeteksi dan sangat cocok untuk serangan mendadak.', null),
  (17, 'Wing Gundam Zero', 'XXXG-00W0', 6, 'Heero Yuy', 'Koloni (Operation Meteor)', 'Transformable (Zero System)', null, null, array['Twin Buster Rifle', 'Beam Saber', 'Machine Cannon'], 'Wing Gundam versi awal dengan Zero System yang menampilkan prediksi pertempuran langsung ke otak pilot. Terkenal bersayap malaikat yang megah dan Twin Buster Rifle yang mematikan.', null),
  (18, 'Shining Gundam', 'GF13-017NJ', 7, 'Domon Kasshu', 'Neo Japan', 'Mobile Fighter', null, null, array['Shining Finger', 'Beam Saber'], 'Mobile Fighter wakil Neo Japan di Gundam Fight ke-13. Bergerak mengikuti gerakan pilotnya lewat sistem Mobile Trace, dengan jurus utama Shining Finger.', null),
  (19, 'God Gundam', 'GF13-017NJII', 7, 'Domon Kasshu', 'Neo Japan', 'Mobile Fighter', null, null, array['God Finger', 'Ishin Denshin'], 'Evolusi Shining Gundam yang dipakai Domon Kasshu di fase akhir turnamen. Jurus andalannya adalah God Finger, serta teknik Ishin Denshin saat semangat pilotnya membara.', null),
  (20, 'Strike Gundam', 'GAT-X105', 8, 'Kira Yamato', 'Earth Alliance', 'Prototipe modular', 17.72, 64.8, array['Beam Rifle', 'Beam Saber', 'Armor Schneider', 'IWSP Striker Pack'], 'Prototipe Earth Alliance dengan sistem Striker Pack yang dapat ditukar sesuai misi. Dikemudikan Kira Yamato yang mengoptimalkan OS-nya langsung di tengah pertempuran.', null),
  (21, 'Freedom Gundam', 'ZGMF-X10A', 8, 'Kira Yamato', 'ZAFT (Three Ships Alliance)', 'Prototipe nuklir', 18.03, 71.5, array['Beam Rifle', 'Beam Saber', 'Rail Gun', 'Full Burst Mode'], 'Gundam bertenaga reaktor nuklir yang dikembangkan ZAFT lalu direbut Three Ships Alliance. Sayap lebarnya menjadi ciri khas, dan mode Full Burst-nya menembakkan seluruh senjata sekaligus.', null),
  (22, 'Justice Gundam', 'ZGMF-X09A', 8, 'Athrun Zala', 'ZAFT', 'Prototipe nuklir', 18.03, 79.17, array['Beam Rifle', 'Beam Saber', 'Fatum-00'], 'Gundam kembaran Freedom milik Athrun Zala. Sistem Fatum-00 di punggungnya bisa dilepas dan dikendalikan terpisah dari bodi utama.', null),
  (23, 'Gundam Exia', 'GN-001', 9, 'Setsuna F. Seiei', 'Celestial Being', 'Jarak dekat', 18.3, 57.5, array['GN Sword', 'GN Long Blade', 'GN Short Blade', 'GN Beam Dagger'], 'Gundam generasi pertama Celestial Being yang mengandalkan GN Drive. Kekuatan jarak dekatnya sangat tinggi dan mode Trans-Am menaikkan seluruh performanya dalam waktu singkat.', null),
  (24, '00 Gundam', 'GN-0000', 9, 'Setsuna F. Seiei', 'Celestial Being', 'Twin Drive', 18.3, null, array['GN Sword', 'GN Beam Saber'], 'Gundam dengan dua GN Drive (Twin Drive) yang menghasilkan energi sangat besar. Dikemudikan Setsuna F. Seiei dan menjadi inti dari pertarungan menghadapi aliansi dunia.', null),
  (25, 'Gundam Barbatos', 'ASW-G-08', 10, 'Mikazuki Augus', 'Tekkadan', 'Gundam Frame', 18, 28.5, array['Mace', 'Lance', '200mm Cannon'], 'Mobile suit berusia ratusan tahun berbasis Gundam Frame dengan dua reaktor Ahab. Gaya bertarungnya brutal dan tanpa banyak senjata, mengandalkan mace berat dan kemampuan Mikazuki.', null),
  (26, 'Gundam Vidar', 'ASW-G-47', 10, 'Gaelio Bauduin', 'Gjallarhorn', 'Gundam Frame', null, null, '{}'::text[], 'Mobile frame Gundam Frame milik Gaelio Bauduin dari Gjallarhorn, organisasi yang menguasai keamanan Bumi. Menjadi lawan sepadan Barbatos dan menunjukkan kekuatan teknologi Gjallarhorn.', null),
  (27, 'Gundam Aerial', 'XVX-016', 11, 'Suletta Mercury', 'Asticassia School of Technology', 'Gundam sekolah', null, null, array['Beam Saber', 'Bit Staves'], 'Gundam yang dipakai Suletta Mercury di Asticassia. Dilengkapi Bit Staves yang berfungsi sebagai perisai dan senjata, serta sistem GUND-Format yang menyimpan rahasia besar.', null)
